CREATE TABLE IF NOT EXISTS users (name TEXT PRIMARY KEY, salt TEXT NOT NULL, password_hash TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions (digest TEXT PRIMARY KEY, username TEXT NOT NULL REFERENCES users(name), expires BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS settings (name TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS categories (name TEXT PRIMARY KEY);
CREATE TABLE IF NOT EXISTS data_sources (name TEXT PRIMARY KEY, url TEXT NOT NULL, mode TEXT NOT NULL, enabled INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS collection_jobs (id TEXT PRIMARY KEY, source TEXT NOT NULL, slot TEXT NOT NULL, state TEXT NOT NULL, attempts INTEGER DEFAULT 0, touched TEXT NOT NULL, detail TEXT DEFAULT '', UNIQUE(source,slot));
CREATE TABLE IF NOT EXISTS raw_items (id TEXT PRIMARY KEY, source TEXT NOT NULL, received TEXT NOT NULL, payload TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS keywords (id TEXT PRIMARY KEY, term TEXT NOT NULL, first_seen TEXT NOT NULL, last_seen TEXT NOT NULL, translation TEXT DEFAULT '', category TEXT DEFAULT '', notes TEXT DEFAULT '', status TEXT DEFAULT '新发现');
CREATE TABLE IF NOT EXISTS keyword_aliases (alias TEXT PRIMARY KEY, keyword_id TEXT REFERENCES keywords(id));
CREATE TABLE IF NOT EXISTS trend_observations (id TEXT PRIMARY KEY, keyword_id TEXT NOT NULL REFERENCES keywords(id), source TEXT NOT NULL, market TEXT NOT NULL, day TEXT NOT NULL, period TEXT NOT NULL, value DOUBLE PRECISION, unit TEXT NOT NULL, confidence TEXT NOT NULL, url TEXT NOT NULL, raw_id TEXT REFERENCES raw_items(id));
CREATE INDEX IF NOT EXISTS observations_series ON trend_observations(keyword_id,source,market,unit,period,day);
CREATE TABLE IF NOT EXISTS images (id TEXT PRIMARY KEY, url TEXT NOT NULL, page TEXT NOT NULL, author TEXT DEFAULT '', discovered TEXT NOT NULL, rights TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS image_relations (image_id TEXT REFERENCES images(id), keyword_id TEXT REFERENCES keywords(id), PRIMARY KEY(image_id,keyword_id));
CREATE TABLE IF NOT EXISTS phrases (id TEXT PRIMARY KEY, keyword_id TEXT REFERENCES keywords(id), phrase TEXT NOT NULL, created TIMESTAMP DEFAULT CURRENT_TIMESTAMP, origin TEXT NOT NULL, translation TEXT NOT NULL, url TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS visual_trends (id TEXT PRIMARY KEY, image_id TEXT REFERENCES images(id), analysis TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS products (id TEXT PRIMARY KEY, name TEXT NOT NULL, url TEXT NOT NULL, notes TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS opportunities (id TEXT PRIMARY KEY, keyword_id TEXT REFERENCES keywords(id), title TEXT NOT NULL, analysis TEXT NOT NULL, created TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS opportunity_evidence (opportunity_id TEXT REFERENCES opportunities(id), raw_id TEXT REFERENCES raw_items(id), PRIMARY KEY(opportunity_id,raw_id));
CREATE TABLE IF NOT EXISTS projects (id TEXT PRIMARY KEY, name TEXT NOT NULL, keyword_id TEXT REFERENCES keywords(id), status TEXT NOT NULL, owner TEXT NOT NULL, due TEXT NOT NULL, notes TEXT NOT NULL, created TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS project_assets (id TEXT PRIMARY KEY, project_id TEXT REFERENCES projects(id), url TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS project_history (id TEXT PRIMARY KEY, project_id TEXT REFERENCES projects(id), recorded TEXT NOT NULL, change_text TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS watchlists (id TEXT PRIMARY KEY, term TEXT NOT NULL, enabled INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS reports (id TEXT PRIMARY KEY, kind TEXT NOT NULL, day TEXT NOT NULL, content TEXT NOT NULL, generated TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS favorites (keyword_id TEXT PRIMARY KEY REFERENCES keywords(id));
CREATE TABLE IF NOT EXISTS ai_analysis_logs (id TEXT PRIMARY KEY, keyword_id TEXT REFERENCES keywords(id), created TEXT NOT NULL, result TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS audit_logs (id TEXT PRIMARY KEY, recorded TEXT NOT NULL, action TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS ai_budget (day TEXT PRIMARY KEY, reserved_micros BIGINT NOT NULL, calls INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS phrase_evidence (phrase_id TEXT REFERENCES phrases(id), raw_id TEXT REFERENCES raw_items(id), seen TEXT NOT NULL, PRIMARY KEY(phrase_id,raw_id));
CREATE TABLE IF NOT EXISTS image_features (image_id TEXT PRIMARY KEY REFERENCES images(id), dhash TEXT NOT NULL, colors TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS review_scores (keyword_id TEXT PRIMARY KEY REFERENCES keywords(id), demand INTEGER, competition INTEGER, personal INTEGER, migration INTEGER, rationale TEXT NOT NULL, ip_status TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS ai_failures (id TEXT PRIMARY KEY, attempts INTEGER NOT NULL, reason TEXT NOT NULL, recorded TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS project_details (project_id TEXT PRIMARY KEY REFERENCES projects(id), content TEXT NOT NULL);
